<?php
/** Secure no-login contribution links for ordinary WordPress news posts. */
if (! defined('ABSPATH')) { exit; }
const SSF_EXTERNAL_NEWS_HASH='_ssf_external_news_token_hash'; const SSF_EXTERNAL_NEWS_EXPIRES='_ssf_external_news_expires_at'; const SSF_EXTERNAL_NEWS_REVOKED='_ssf_external_news_revoked'; const SSF_EXTERNAL_NEWS_AUDIT='_ssf_external_news_audit'; const SSF_EXTERNAL_NEWS_GALLERY='_ssf_external_news_gallery_ids'; const SSF_EXTERNAL_NEWS_RECIPIENT='_ssf_external_news_recipient'; const SSF_EXTERNAL_NEWS_INVITED_AT='_ssf_external_news_invited_at'; const SSF_EXTERNAL_NEWS_STARTED_AT='_ssf_external_news_started_at';
function ssf_external_news_token(): string { return rtrim(strtr(base64_encode(random_bytes(32)),'+/','-_'),'='); }
function ssf_external_news_url(string $token): string { return home_url('/skriv-nyhet/'.rawurlencode($token).'/'); }
function ssf_external_news_audit(int $id,string $event): void { $a=(array)get_post_meta($id,SSF_EXTERNAL_NEWS_AUDIT,true); $a[]=array('event'=>sanitize_key($event),'time'=>current_time('mysql')); update_post_meta($id,SSF_EXTERNAL_NEWS_AUDIT,array_slice($a,-100)); }
function ssf_external_news_find(string $token): ?WP_Post { if(!preg_match('/^[A-Za-z0-9_-]{43}$/',$token)){return null;} $hash=hash('sha256',$token); $items=get_posts(array('post_type'=>'post','post_status'=>array('draft','pending'),'posts_per_page'=>1,'meta_key'=>SSF_EXTERNAL_NEWS_HASH,'meta_value'=>$hash)); if(!$items){return null;} $p=$items[0]; return hash_equals((string)get_post_meta($p->ID,SSF_EXTERNAL_NEWS_HASH,true),$hash)&&!get_post_meta($p->ID,SSF_EXTERNAL_NEWS_REVOKED,true)&&(int)get_post_meta($p->ID,SSF_EXTERNAL_NEWS_EXPIRES,true)>=time()?$p:null; }
function ssf_external_news_set_token(int $id,int $expires): string { $token=ssf_external_news_token(); update_post_meta($id,SSF_EXTERNAL_NEWS_HASH,hash('sha256',$token)); update_post_meta($id,SSF_EXTERNAL_NEWS_EXPIRES,$expires); update_post_meta($id,SSF_EXTERNAL_NEWS_REVOKED,'0'); return $token; }
function ssf_external_news_status(WP_Post $p): string { if(get_post_meta($p->ID,SSF_EXTERNAL_NEWS_REVOKED,true)){return 'Återkallad';} if((int)get_post_meta($p->ID,SSF_EXTERNAL_NEWS_EXPIRES,true)<time()){return 'Utgången';} if('pending'===$p->post_status){return 'Inskickad för granskning';} if('publish'===$p->post_status){return 'Publicerad';} if(get_post_meta($p->ID,SSF_EXTERNAL_NEWS_STARTED_AT,true)){return 'Påbörjad';} return get_post_meta($p->ID,SSF_EXTERNAL_NEWS_INVITED_AT,true)?'Inbjudan skickad':'Utkast'; }
function ssf_external_news_send_invitation(int $id,string $recipient,string $token): bool { if(!class_exists('SSF_Email_Template')||!is_email($recipient)){return false;} $expires=(int)get_post_meta($id,SSF_EXTERNAL_NEWS_EXPIRES,true); $ok=SSF_Email_Template::send($recipient,'Du har blivit inbjuden att skriva en nyhet för Sveriges Segelfartygsförbund','contact_confirmation',array('category'=>'general','title'=>'Skriv en nyhet för SSF','preheader'=>'Du har fått en säker länk för att skriva ett nyhetsutkast.','body'=>array('Du har blivit inbjuden att skriva ett nyhetsutkast för Sveriges Segelfartygsförbund.','Du behöver inget konto. Länken gäller till '.wp_date('Y-m-d',$expires).'.','Vidarebefordra inte länken, eftersom den ger tillgång till utkastet.'),'button_label'=>'Skriv nyheten','button_url'=>ssf_external_news_url($token))); if($ok){update_post_meta($id,SSF_EXTERNAL_NEWS_INVITED_AT,current_time('mysql'));ssf_external_news_audit($id,'invitation_sent');} return $ok; }
function ssf_external_news_register_route(): void { add_rewrite_rule('^skriv-nyhet/([^/]+)/?$','index.php?ssf_external_news_token=$matches[1]','top');if('2'!==get_option('ssf_external_news_rewrite_version')){flush_rewrite_rules(false);update_option('ssf_external_news_rewrite_version','2',false);} }
add_action('init','ssf_external_news_register_route'); add_filter('query_vars',static function(array $v):array{$v[]='ssf_external_news_token';return $v;}); add_filter('wp_robots',static function(array $r):array{if(get_query_var('ssf_external_news_token')){$r['noindex']=true;$r['nofollow']=true;}return $r;}); add_action('template_redirect','ssf_external_news_render_editor',0);
function ssf_external_news_preview_url(string $t,string $context='home',string $device='desktop'):string{return add_query_arg(array('view'=>'preview','context'=>$context,'device'=>$device),ssf_external_news_url($t));}
function ssf_external_news_render_editor():void { $t=(string)get_query_var('ssf_external_news_token');if(!$t)return;nocache_headers();header('X-Robots-Tag: noindex, nofollow, noarchive',true);$p=ssf_external_news_find($t);status_header($p?200:404);get_header();echo '<main id="ssf-external-news" class="ssf-external-news"><section class="ssf-external-news__card"><p class="ssf-external-news__brand">Sveriges Segelfartygsförbund</p><h1>Skriv en nyhet</h1>';if(!$p){echo '<p>Länken är inte längre giltig. Kontakta SSF om du behöver en ny länk.</p></section></main>';get_footer();exit;}$submitted='pending'===$p->post_status;$view='preview'===sanitize_key((string)($_GET['view']??''))?'preview':'edit';$notice=sanitize_key((string)($_GET['ssf_external_news_notice']??''));if($notice){echo '<div class="ssf-external-news__notice">'.('submitted'===$notice?'✓ Nyheten har skickats till SSF för granskning':'✓ Utkastet är sparat').'</div>';}echo '<p class="ssf-external-news__state">'.esc_html(ssf_external_news_status($p)).'</p><nav class="ssf-external-news__nav"><a href="'.esc_url(ssf_external_news_url($t)).'">Redigera</a><a href="'.esc_url(ssf_external_news_preview_url($t)).'">Förhandsgranska</a></nav>';if($submitted){echo '<p class="ssf-external-news__notice">Nyheten väntar på granskning.</p></section></main>';get_footer();exit;}if('preview'===$view){ssf_external_news_render_preview($p,$t);echo '</section></main>';get_footer();exit;}echo '<form method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'" class="ssf-external-news__form"><input type="hidden" name="action" value="ssf_external_news_save"><input type="hidden" name="token" value="'.esc_attr($t).'">';wp_nonce_field('ssf_external_news_'.hash('sha256',$t),'ssf_external_news_nonce');echo '<label>Rubrik<input type="text" name="title" required value="'.esc_attr($p->post_title).'"></label><label>Ingress / sammanfattning<textarea name="excerpt" rows="3">'.esc_textarea($p->post_excerpt).'</textarea></label><label>Nyhetstext</label>';wp_editor($p->post_content,'ssf_external_news_content',array('textarea_name'=>'content','media_buttons'=>false,'textarea_rows'=>14,'teeny'=>true));echo '<label>Huvudbild<input type="file" name="featured_image" accept="image/jpeg,image/png,image/webp"></label><label>Fler bilder<input type="file" name="gallery_images[]" accept="image/jpeg,image/png,image/webp" multiple></label><p class="description">Endast JPEG, PNG och WebP-bilder kan laddas upp.</p><div><button type="submit" name="intent" value="save" class="ssf-button">Spara utkast</button><button type="submit" name="intent" value="preview" class="ssf-button">Förhandsgranska</button><button type="submit" name="intent" value="submit" class="ssf-button ssf-button--primary">Skicka till SSF</button></div></form></section></main>';get_footer();exit; }
function ssf_external_news_render_preview(WP_Post $p,string $t):void{$c='article'===sanitize_key((string)($_GET['context']??'home'))?'article':'home';$d='mobile'===sanitize_key((string)($_GET['device']??''))?'mobile':'desktop';echo '<div class="ssf-external-news__preview-nav"><a href="'.esc_url(ssf_external_news_preview_url($t,'home',$d)).'">Startsida</a><a href="'.esc_url(ssf_external_news_preview_url($t,'article',$d)).'">Nyhetssida</a><a href="'.esc_url(ssf_external_news_preview_url($t,$c,'desktop')).'">Desktop</a><a href="'.esc_url(ssf_external_news_preview_url($t,$c,'mobile')).'">Mobil</a></div><div class="ssf-external-news__preview ssf-external-news__preview--'.esc_attr($d).'">';if('home'===$c&&function_exists('ssf_site_render_news_card')){echo '<div class="ssf-news-grid">'.ssf_site_render_news_card($p,ssf_external_news_preview_url($t,'article',$d)).'</div>';}elseif('article'===$c&&function_exists('ssf_render_news_article')){ssf_render_news_article($p);}echo '</div><p><a href="'.esc_url(ssf_external_news_url($t)).'">← Tillbaka till Redigera</a></p>';}
function ssf_external_news_upload(int $id,array $f):int{if(empty($f['tmp_name'])||UPLOAD_ERR_OK!==(int)($f['error']??UPLOAD_ERR_NO_FILE)||!is_uploaded_file($f['tmp_name'])||(int)$f['size']>wp_max_upload_size())return 0;$checked=wp_check_filetype_and_ext($f['tmp_name'],$f['name']);if(!in_array($checked['type']??'',array('image/jpeg','image/png','image/webp'),true)||!in_array(strtolower((string)($checked['ext']??'')),array('jpg','jpeg','png','webp'),true))return 0;require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/image.php';require_once ABSPATH.'wp-admin/includes/media.php';$a=media_handle_sideload($f,$id);return is_wp_error($a)?0:(int)$a;}
function ssf_external_news_save():void{$t=sanitize_text_field(wp_unslash($_POST['token']??''));$p=ssf_external_news_find($t);if(!$p||!isset($_POST['ssf_external_news_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['ssf_external_news_nonce'])),'ssf_external_news_'.hash('sha256',$t))){wp_die('Länken är inte längre giltig.',403);}$i=sanitize_key(wp_unslash($_POST['intent']??'save'));if(!in_array($i,array('save','preview','submit'),true))$i='save';wp_update_post(array('ID'=>$p->ID,'post_title'=>sanitize_text_field(wp_unslash($_POST['title']??'')),'post_excerpt'=>sanitize_textarea_field(wp_unslash($_POST['excerpt']??'')),'post_content'=>wp_kses_post(wp_unslash($_POST['content']??'')),'post_status'=>'submit'===$i?'pending':'draft'));if(!get_post_meta($p->ID,SSF_EXTERNAL_NEWS_STARTED_AT,true))update_post_meta($p->ID,SSF_EXTERNAL_NEWS_STARTED_AT,current_time('mysql'));if(!empty($_FILES['featured_image'])){$a=ssf_external_news_upload($p->ID,$_FILES['featured_image']);if($a)set_post_thumbnail($p->ID,$a);}$g=array();foreach((array)($_FILES['gallery_images']['name']??array())as $n=>$name){$a=ssf_external_news_upload($p->ID,array('name'=>$name,'tmp_name'=>$_FILES['gallery_images']['tmp_name'][$n]??'','error'=>$_FILES['gallery_images']['error'][$n]??UPLOAD_ERR_NO_FILE,'size'=>$_FILES['gallery_images']['size'][$n]??0));if($a)$g[]=$a;}if($g)update_post_meta($p->ID,SSF_EXTERNAL_NEWS_GALLERY,array_merge((array)get_post_meta($p->ID,SSF_EXTERNAL_NEWS_GALLERY,true),$g));ssf_external_news_audit($p->ID,'submit'===$i?'submitted':'saved');$url='preview'===$i?ssf_external_news_preview_url($t):add_query_arg('ssf_external_news_notice','submit'===$i?'submitted':'saved',ssf_external_news_url($t));wp_safe_redirect($url);exit;}
add_action('admin_post_nopriv_ssf_external_news_save','ssf_external_news_save');add_action('admin_post_ssf_external_news_save','ssf_external_news_save');
function ssf_external_news_admin_menu():void{$parent=class_exists('SSF_Admin_Navigation')?SSF_Admin_Navigation::CONTENT:'edit.php';add_submenu_page($parent,'Externa nyheter','Externa nyheter','edit_posts','ssf-external-news','ssf_external_news_admin_page',35);}add_action('admin_menu','ssf_external_news_admin_menu');
function ssf_external_news_redirect(string $text,string $type='success'):void{set_transient('ssf_external_news_notice_'.get_current_user_id(),array($text,$type),MINUTE_IN_SECONDS);wp_safe_redirect(admin_url('admin.php?page=ssf-external-news'));exit;}
function ssf_external_news_admin_page():void{if(!current_user_can('edit_posts'))wp_die('Du saknar behörighet.');$n=get_transient('ssf_external_news_notice_'.get_current_user_id());if($n){delete_transient('ssf_external_news_notice_'.get_current_user_id());echo '<div class="notice notice-'.esc_attr($n[1]).'"><p>'.esc_html($n[0]).'</p></div>';} $created=get_transient('ssf_external_news_created_'.get_current_user_id());if($created)delete_transient('ssf_external_news_created_'.get_current_user_id());echo '<div class="wrap"><h1>Externa nyheter</h1><div class="card"><h2>Bjud in extern skribent</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="ssf_external_news_create">';wp_nonce_field('ssf_external_news_create');echo '<p><label>E-postadress<br><input class="regular-text" type="email" required name="recipient"></label></p><p><label>Nyhetens arbetsrubrik<br><input class="regular-text" name="title"></label></p><p><label>Länken gäller till<br><input type="date" required name="expires_on" value="'.esc_attr(wp_date('Y-m-d',time()+14*DAY_IN_SECONDS)).'"></label></p>';submit_button('Skapa och skicka länk');echo '</form></div>';if($created)echo '<div class="notice notice-success"><p><strong>Ny säker länk skapades.</strong><br><input class="large-text code" readonly value="'.esc_attr(ssf_external_news_url($created)).'"></p></div>';echo '<h2>Inbjudningar och utkast</h2><table class="widefat striped"><thead><tr><th>Nyhet</th><th>Mottagare</th><th>Status</th><th>Senast ändrad</th><th>Länk giltig till</th><th>Åtgärder</th></tr></thead><tbody>';$posts=get_posts(array('post_type'=>'post','post_status'=>array('draft','pending','publish'),'posts_per_page'=>100,'meta_key'=>SSF_EXTERNAL_NEWS_HASH));foreach($posts as $p){$active=!get_post_meta($p->ID,SSF_EXTERNAL_NEWS_REVOKED,true)&&(int)get_post_meta($p->ID,SSF_EXTERNAL_NEWS_EXPIRES,true)>=time()&&'draft'===$p->post_status;echo '<tr><td><a href="'.esc_url(get_edit_post_link($p->ID)).'">'.esc_html($p->post_title?:'Namnlöst utkast').'</a></td><td>'.esc_html((string)get_post_meta($p->ID,SSF_EXTERNAL_NEWS_RECIPIENT,true)).'</td><td>'.esc_html(ssf_external_news_status($p)).'</td><td>'.esc_html(get_the_modified_date('Y-m-d H:i',$p)).'</td><td>'.esc_html(wp_date('Y-m-d H:i',(int)get_post_meta($p->ID,SSF_EXTERNAL_NEWS_EXPIRES,true))).'</td><td><a class="button button-small" href="'.esc_url(get_edit_post_link($p->ID)).'">'.('pending'===$p->post_status?'Granska':'Öppna utkast').'</a> ';if($active){foreach(array('resend'=>'Skicka länken igen','copy'=>'Kopiera länk','revoke'=>'Återkalla')as $a=>$label){echo '<form style="display:inline" method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="ssf_external_news_'.$a.'"><input type="hidden" name="post_id" value="'.esc_attr((string)$p->ID).'">';if('resend'===$a)echo '<input type="email" name="recipient" value="'.esc_attr((string)get_post_meta($p->ID,SSF_EXTERNAL_NEWS_RECIPIENT,true)).'">';wp_nonce_field('ssf_external_news_'.$a.'_'.$p->ID);echo '<button class="button button-small" type="submit">'.esc_html($label).'</button></form> ';}}echo '</td></tr>';}echo '</tbody></table></div>';}
function ssf_external_news_create():void{if(!current_user_can('edit_posts')||!check_admin_referer('ssf_external_news_create'))wp_die('Du saknar behörighet.');$r=sanitize_email(wp_unslash($_POST['recipient']??''));$expires=strtotime(sanitize_text_field(wp_unslash($_POST['expires_on']??'')).' 23:59:59');if(!is_email($r)||!$expires||$expires<time())ssf_external_news_redirect('Ange giltig e-postadress och framtida datum.','error');$id=wp_insert_post(array('post_type'=>'post','post_status'=>'draft','post_title'=>sanitize_text_field(wp_unslash($_POST['title']??''))?:'Namnlöst utkast','post_author'=>get_current_user_id()),true);if(is_wp_error($id))wp_die('Kunde inte skapa utkastet.');update_post_meta($id,SSF_EXTERNAL_NEWS_RECIPIENT,$r);$t=ssf_external_news_set_token($id,$expires);ssf_external_news_audit($id,'link_created');if(!ssf_external_news_send_invitation($id,$r,$t))ssf_external_news_redirect('Utkastet skapades men e-post kunde inte skickas.','error');set_transient('ssf_external_news_created_'.get_current_user_id(),$t,10*MINUTE_IN_SECONDS);ssf_external_news_redirect('Inbjudan har skickats.');}add_action('admin_post_ssf_external_news_create','ssf_external_news_create');
function ssf_external_news_resend():void{$id=absint($_POST['post_id']??0);$r=sanitize_email(wp_unslash($_POST['recipient']??''));if(!$id||!is_email($r)||!current_user_can('edit_post',$id)||!check_admin_referer('ssf_external_news_resend_'.$id))wp_die('Du saknar behörighet.');$t=ssf_external_news_set_token($id,time()+14*DAY_IN_SECONDS);update_post_meta($id,SSF_EXTERNAL_NEWS_RECIPIENT,$r);ssf_external_news_audit($id,'invitation_resent');if(!ssf_external_news_send_invitation($id,$r,$t))ssf_external_news_redirect('Den nya länken skapades men e-post kunde inte skickas.','error');ssf_external_news_redirect('Ny länk skickades. Den tidigare länken är ogiltig.');}add_action('admin_post_ssf_external_news_resend','ssf_external_news_resend');
function ssf_external_news_copy():void{$id=absint($_POST['post_id']??0);if(!$id||!current_user_can('edit_post',$id)||!check_admin_referer('ssf_external_news_copy_'.$id))wp_die('Du saknar behörighet.');$t=ssf_external_news_set_token($id,time()+14*DAY_IN_SECONDS);ssf_external_news_audit($id,'link_regenerated');set_transient('ssf_external_news_created_'.get_current_user_id(),$t,10*MINUTE_IN_SECONDS);ssf_external_news_redirect('Ny länk skapades. Den tidigare länken är ogiltig.');}add_action('admin_post_ssf_external_news_copy','ssf_external_news_copy');
function ssf_external_news_revoke():void{$id=absint($_POST['post_id']??0);if(!$id||!current_user_can('edit_post',$id)||!check_admin_referer('ssf_external_news_revoke_'.$id))wp_die('Du saknar behörighet.');update_post_meta($id,SSF_EXTERNAL_NEWS_REVOKED,'1');ssf_external_news_audit($id,'link_revoked');ssf_external_news_redirect('Länken är återkallad.');}add_action('admin_post_ssf_external_news_revoke','ssf_external_news_revoke');
add_action('transition_post_status',static function(string $new,string $old,WP_Post $p):void{if('post'===$p->post_type&&'publish'===$new&&'publish'!==$old&&get_post_meta($p->ID,SSF_EXTERNAL_NEWS_HASH,true))ssf_external_news_audit($p->ID,'admin_published');},10,3);
